package org.humanjourney.core.advancement;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class NativePresentationTest {
 static Path project(){return Path.of(System.getProperty("humanjourney.projectDir"));}
 static JsonObject example()throws Exception{return JsonParser.parseString(Files.readString(project().resolve("example-native-advancements-datapack/data/human_journey/core/advancement_presentation.json"))).getAsJsonObject();}
 static NativePresentation parse(JsonObject root){return NativePresentation.parse(root,id->!id.contains("missing"));}
 static NativePresentation.Tab tab()throws Exception{return parse(example()).tabs().getFirst();}
 static Map<String,NativePresentation.Widget> widgets(NativePresentation.Tab t){var result=new HashMap<String,NativePresentation.Widget>();for(var p:t.positions())result.put(p.advancement(),new NativePresentation.Widget(p.advancement(),"",p.x(),p.y(),true));return result;}
 @Test void threeConvergingDefinitionsYieldTwoExtraLinksPlusUnchangedNativeParent()throws Exception{var t=tab();var w=widgets(t);assertEquals(3,NativePresentation.drawable(t,w).size());var edge=t.connections().getLast();var target=w.get(edge.to());w.put(target.id(),new NativePresentation.Widget(target.id(),edge.from(),target.x(),target.y(),true));assertEquals(3,t.connections().size());assertEquals(2,NativePresentation.drawable(t,w).size());}
 @Test void unavailableHiddenOrMissingWidgetsNeverHaveExtraConnections()throws Exception{var t=tab();var w=widgets(t);var target=t.connections().getFirst().to();var n=w.get(target);w.put(target,new NativePresentation.Widget(n.id(),n.parent(),n.x(),n.y(),false));assertTrue(NativePresentation.drawable(t,w).isEmpty());w.remove(target);assertTrue(NativePresentation.drawable(t,w).isEmpty());}
 @Test void routesUseActualWidgetCentresAndRetainWaypoints()throws Exception{var t=tab();var route=NativePresentation.route(t.connections().getFirst(),widgets(t));assertEquals(t.connections().getFirst().route(),route.subList(1,route.size()-1));assertEquals(new NativePresentation.Point(503,117),route.getLast());}
 @Test void nativeOffsetsKeepExtraLinksAlignedWhenPanned()throws Exception{var t=tab();var route=NativePresentation.route(t.connections().getFirst(),widgets(t));for(int sx:List.of(-400,-20,0,100))for(int sy:List.of(-200,0,40)){var end=route.getLast();assertEquals(503+sx,end.x()+sx);assertEquals(117+sy,end.y()+sy);}}
 @Test void syntheticTwoEraRegionsUseExistingAdvancementIdsOnly()throws Exception{var model=NativePresentation.read(Files.readString(project().resolve("src/test/resources/native-advancements/two-eras.json")),id->true);assertEquals(2,model.tabs().getFirst().eras().size());assertNotEquals(model.tabs().getFirst().eras().get(0).color(),model.tabs().getFirst().eras().get(1).color());assertEquals(tab().ids(),model.tabs().getFirst().ids());}
 @Test void serverPruningRemovesHiddenIdsRoutesAndEraMetadata()throws Exception{var o=example();var eras=o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("eras");var secret=eras.get(0).deepCopy().getAsJsonObject();secret.addProperty("id","secret");secret.addProperty("title","SECRET_ERA");var members=new JsonArray();members.add("human_journey:era0/we_can_stay");secret.add("members",members);eras.add(secret);var model=parse(o);var filtered=model.visible(Set.of(tab().root()));assertEquals(1,filtered.tabs().getFirst().eras().size());assertTrue(filtered.tabs().getFirst().connections().isEmpty());assertFalse(filtered.json().contains("SECRET"));assertFalse(filtered.json().contains("we_can_stay"));assertTrue(model.visible(Set.of()).tabs().isEmpty());}
 @Test void unknownAdvancementReferencesAreRejected()throws Exception{var o=example();o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("positions").get(0).getAsJsonObject().addProperty("advancement","human_journey:missing");assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void ordinaryMinecraftRootsCannotBeEnhanced()throws Exception{var o=example();o.getAsJsonArray("tabs").get(0).getAsJsonObject().addProperty("root","minecraft:story/root");assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void schemaGameplayFieldsAndNonIntegralCoordinatesReject()throws Exception{var a=example();a.addProperty("schema_version",2);assertThrows(IllegalArgumentException.class,()->parse(a));var b=example();b.addProperty("completion","score");assertThrows(IllegalArgumentException.class,()->parse(b));var c=example();c.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("positions").get(0).getAsJsonObject().addProperty("x",.5);assertThrows(IllegalArgumentException.class,()->parse(c));}
 @Test void duplicatePhysicalLinksRejectEvenWhenReversed()throws Exception{var o=example();var a=o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("connections");var first=a.get(0).deepCopy().getAsJsonObject();var from=first.get("from");first.add("from",first.get("to"));first.add("to",from);a.add(first);assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void textureMustBeLocalAndNoArbitraryUrlIsLoaded()throws Exception{for(String bad:List.of("https://bad/a.png","C:/bad.png","minecraft:../a.png")){var o=example();o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("eras").get(0).getAsJsonObject().addProperty("texture",bad);assertThrows(IllegalArgumentException.class,()->parse(o));}}
 @Test void absentPresentationIsExactlyEmptyAndStableReloadIsDeterministic()throws Exception{assertTrue(NativePresentation.empty().tabs().isEmpty());assertEquals(parse(example()),parse(example()));assertEquals(parse(example()),NativePresentation.read(parse(example()).json(),id->true));}
 @Test void onlyExactInspectedVersionsAreEnabled(){assertTrue(NativeMixinPlugin.supported("1.21.8","58.1.18"));assertFalse(NativeMixinPlugin.supported("1.21.9","58.1.18"));assertFalse(NativeMixinPlugin.supported("1.21.8","58.1.19"));}
 @Test void missingLocalTextureIsDiagnosedBeforeAnyRendering()throws Exception{var o=example();o.getAsJsonArray("tabs").get(0).getAsJsonObject().getAsJsonArray("eras").get(0).getAsJsonObject().addProperty("texture","minecraft:textures/block/stone.png");var t=parse(o).tabs().getFirst();var e=assertThrows(IllegalArgumentException.class,()->NativePresentation.textures(t,id->false));assertTrue(e.getMessage().contains("minecraft:textures/block/stone.png"));assertDoesNotThrow(()->NativePresentation.textures(t,id->true));}
}
